const state={logs:structuredClone(seed),route:'S04',viewState:'content',selectedId:'DEMO-01',guideId:'bottle',query:'',filter:{category:'',method:'',from:'',to:''},range:7,draft:null,dirty:false,name:'Pengguna Demo',reminder:false,time:'20:00',photo:null,photoName:'',galleryGroup:'all',theme:'light',lastNew:true};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.more}"/></svg>`;
const button=(text,attrs='',style='primary')=>`<button class="btn ${style}" ${attrs}>${text}</button>`;
const goto=(text,id,style='primary')=>button(text,`data-go="${id}"`,style);
const badge=m=>`<span class="badge ${m.toLowerCase()}">${methods[m]}</span>`;
const number=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:3}).format(n);
const mass=g=>g>=1000?`${number(g/1000)} kg`:`${number(g)} g`;
const shortDate=d=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(`${d}T12:00:00Z`));
const value=l=>l.weight?mass(l.weight):`${number(l.count)} benda`;
function totals(logs){const handled=logs.filter(x=>x.method!=='REDUCE'),avoided=logs.filter(x=>x.method==='REDUCE');return {weight:handled.reduce((n,x)=>n+x.weight,0),count:handled.reduce((n,x)=>n+x.count,0),avoidedWeight:avoided.reduce((n,x)=>n+x.weight,0),avoidedCount:avoided.reduce((n,x)=>n+x.count,0),handled:handled.length,recycled:handled.filter(x=>x.method==='RECYCLE').length,rate:handled.length?handled.filter(x=>x.method==='RECYCLE').length/handled.length*100:null,activities:logs.length};}
function streak(logs){const days=new Set(logs.map(x=>x.date));let d=new Date(TODAY+'T12:00:00Z'),n=0;if(!days.has(TODAY))d.setUTCDate(d.getUTCDate()-1);while(days.has(d.toISOString().slice(0,10))){n++;d.setUTCDate(d.getUTCDate()-1);}return n;}
function bestStreak(logs){let best=0,current=0,previous=null;for(const day of [...new Set(logs.map(x=>x.date))].sort()){const date=Date.parse(day+'T12:00:00Z');current=previous!==null&&date-previous===86400000?current+1:1;best=Math.max(best,current);previous=date;}return best;}
function parseQuantity(raw,unit){const text=String(raw).trim();if(!['g','kg','pcs'].includes(unit)||!/^\d+(?:[.,]\d+)?$/.test(text))return null;const decimals=text.split(/[.,]/)[1]||'';if((unit!=='kg'&&decimals.length)||decimals.length>3)return null;const n=Number(text.replace(',','.')),canonical=unit==='kg'?Math.round(n*1000):n;if(!Number.isSafeInteger(canonical)||canonical<1||canonical>(unit==='pcs'?10000:100000))return null;return {weight:unit==='pcs'?0:canonical,count:unit==='pcs'?canonical:0};}
function optionList(obj,current,empty='Pilih satu'){return `<option value="">${empty}</option>`+Object.entries(obj).map(([k,v])=>`<option value="${k}" ${k===current?'selected':''}>${v}</option>`).join('');}
function field(label,name,opts={}){return `<label class="field">${label}<input name="${name}" type="${opts.type||'text'}" value="${esc(opts.value||'')}" ${opts.required?'required':''} ${opts.extra||''} placeholder="${esc(opts.placeholder||'')}">${opts.hint?`<span class="field-hint">${opts.hint}</span>`:''}</label>`;}
function header(title,back='S04',action=''){return `<div class="phone-title">${back?`<button class="icon-btn" data-go="${back}" aria-label="Kembali">${icon('back')}</button>`:''}<h2>${title}</h2>${action}</div>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="Navigasi aplikasi"><button class="scan-dock-action" data-scan-open="camera" aria-label="Catat atau scan sampah">${icon('camera')}<span>Catat / Scan</span></button>${navItems.map(([id,label,i])=>`<button data-go="${id}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${label}</button>`).join('')}</nav>`;}
function logRow(l){return `<button class="log-row" data-log="${l.id}"><span class="category-icon cat-${l.category.toLowerCase()}">${icon(categoryIcons[l.category])}</span><span class="grow"><strong>${categories[l.category]}</strong><small>${methods[l.method]} · ${shortDate(l.date)}</small></span><span class="log-value">${value(l)}${l.method==='REDUCE'?'<small>dihindari</small>':''}</span></button>`;}
function progress(logs){const xp=logs.length*10,level=Math.floor(xp/100)+1;return `<div class="stack"><div class="row between"><span class="badge recycle">Level ${level}</span><span class="small muted">${xp} XP total</span></div><progress max="100" value="${xp%100}" aria-label="${xp%100} dari 100 XP menuju level berikutnya"></progress><span class="small muted">${100-xp%100} XP lagi ke level ${level+1}</span></div>`;}
function emptyState(kind='empty',context='riwayat'){
 const states={empty:['history','Belum ada catatan',`Mulai dari satu aktivitas hari ini. Catatanmu akan muncul di ${context}.`,'Catat aktivitas','S05'],loading:['clock',`Memuat ${context}…`,'Menyiapkan informasi yang kamu perlukan.',null,null],error:['alert',`${context[0].toUpperCase()+context.slice(1)} belum bisa dimuat`,'Periksa koneksi lalu coba lagi.','Coba lagi',null],offline:['wifi','Koneksi terputus','Isianmu tetap tersedia. Sambungkan internet untuk mencoba lagi.','Coba lagi',null],session:['user','Sesi telah berakhir','Masuk lagi untuk membuka catatanmu.','Masuk','S02'],filtered:['filter','Tidak ada catatan yang cocok','Coba ubah kategori, metode, atau tanggal.','Reset filter',null]};
 if(kind==='empty'&&context==='panduan')states.empty=['guide','Belum ada panduan','Artikel yang telah ditinjau akan tersedia di sini.','Muat ulang panduan','S11'];
 if(kind==='empty'&&context==='detail')states.empty=['history','Catatan tidak tersedia','Catatan mungkin sudah dihapus. Kembali ke riwayat untuk memilih catatan lain.','Lihat riwayat','S07'];
 if(kind==='empty'&&context==='statistik')states.empty=['stats','Belum ada catatan pada periode ini','Catat aktivitas atau pilih periode lain untuk melihat ringkasan.','Catat aktivitas','S05'];
 if(kind==='empty'&&context==='achievement')states.empty=['award','Belum ada pencapaian','Catat satu aktivitas untuk mulai membangun progres.','Catat aktivitas','S05'];
 if(kind==='empty'&&context==='profil')states.empty=['user','Belum ada progres','Mulai mencatat untuk melihat XP dan kebiasaanmu.','Catat aktivitas','S05'];
 const [i,title,desc,action,id]=states[kind]||states.empty;
 return `<div class="state-box"><div class="state-symbol">${icon(i)}</div><h3>${title}</h3><p>${desc}</p>${action?(id?goto(action,id):button(action,`data-action="${kind==='filtered'?'clear-filter':'retry'}"`)): '<progress aria-label="Sedang memuat"></progress>'}</div>`;
}
function newDraft(){return {category:'',method:'',unit:'g',quantity:'',date:TODAY,notes:''};}
function draftFor(log){return {category:log.category,method:log.method,unit:log.weight?'g':'pcs',quantity:String(log.weight||log.count),date:log.date,notes:log.notes};}
function editor(preview,edit){const d=preview?draftFor(seed[0]):(state.draft||newDraft());return `${header(edit?'Ubah catatan':'Catat aktivitas',edit?'S08':'S04')}<form data-form="log" class="stack" novalidate><div class="field"><span class="field-label">Cara pengelolaan</span><div class="method-options" role="radiogroup" aria-label="Cara pengelolaan">${Object.entries(methods).map(([k,v])=>`<label class="method-option"><input type="radio" name="method" value="${k}" ${d.method===k?'checked':''}><span>${v}<small>${methodHints[k]}</small></span></label>`).join('')}</div></div><div class="group-card glass-form pad"><label class="field">Kategori<select name="category" required>${optionList(categories,d.category,'Pilih kategori')}</select></label><div class="field"><span class="field-label">${d.method==='REDUCE'?'Jumlah yang dihindari':d.unit==='pcs'?'Jumlah benda':'Berat'}</span><div class="quantity-compound"><input name="quantity" inputmode="decimal" aria-label="${d.method==='REDUCE'?'Jumlah yang dihindari':d.unit==='pcs'?'Jumlah benda':'Berat'}" value="${esc(d.quantity)}" placeholder="${d.unit==='pcs'?'Contoh: 2':'Contoh: 250'}" required><select name="unit" aria-label="Satuan"><option value="g" ${d.unit==='g'?'selected':''}>g</option><option value="kg" ${d.unit==='kg'?'selected':''}>kg</option><option value="pcs" ${d.unit==='pcs'?'selected':''}>Benda</option></select></div></div>${d.method==='REDUCE'?'<p class="small muted">Reduce dicatat terpisah dari sampah ditangani.</p>':''}${field('Tanggal aktivitas','date',{type:'date',value:d.date,required:true,extra:`min="${edit&&d.date<MIN_DATE?d.date:MIN_DATE}" max="${TODAY}"`})}</div><div class="group-card glass-form pad"><label class="field"><span>Catatan <span class="muted">(opsional)</span></span><textarea name="notes" maxlength="500" placeholder="Konteks singkat aktivitas">${esc(d.notes)}</textarea></label><button type="button" class="text-link" data-go="S18">${icon('camera')} Lampiran foto (opsional)</button></div><p data-form-error class="notice error" role="alert" hidden></p>${button(state.viewState==='loading'&&!preview?'Menyimpan catatan…':edit?'Simpan perubahan':'Simpan catatan',`type="submit" ${state.viewState==='loading'&&!preview?'disabled':''}`)}</form>`;}
function chart(logs,range=7){const dates=Array.from({length:range},(_,i)=>{const d=new Date(TODAY+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(range-1-i));return d.toISOString().slice(0,10);});const vals=dates.map(date=>totals(logs.filter(l=>l.date===date)).weight);const max=Math.max(...vals,1);if(range===30)return `<div class="chart" style="gap:3px" role="img" aria-label="Berat ditangani 30 hari dalam gram: ${dates.map((d,i)=>`${shortDate(d)} ${vals[i]}`).join(', ')}">${dates.map((d,i)=>`<div class="chart-col" title="${shortDate(d)}: ${vals[i]} g"><div class="chart-bar" style="height:${vals[i]/max*95}px"></div></div>`).join('')}</div><p class="small muted">30 hari hingga 21 Sep · gram</p>${dailyTable(dates,vals)}`;
return `<div class="chart" role="img" aria-label="Berat ditangani per hari. ${dates.map((d,i)=>`${shortDate(d)} ${vals[i]} gram`).join(', ')}">${dates.map((d,i)=>`<div class="chart-col"><span class="chart-value">${vals[i]||''}</span><div class="chart-bar" style="height:${vals[i]/max*90}px"></div><span>${d.slice(-2)}</span></div>`).join('')}</div><p class="small muted">7 hari · gram</p>${dailyTable(dates,vals)}`;}
function dailyTable(dates,values){return `<details><summary>Lihat angka harian</summary>${dates.map((d,i)=>`<div class="metric-line"><span>${shortDate(d)}</span><span>${number(values[i])} g</span></div>`).join('')}</details>`;}
function screenContent(id,preview=false){const logs=preview?seed:state.logs;const selected=preview?seed[0]:(logs.find(x=>x.id===state.selectedId)||logs[0]);const guide=guides.find(g=>g.id===(preview?'bottle':state.guideId))||guides[0];const dataScreens=['S04','S07','S08','S11','S12','S13','S14','S15'];
 if(!preview&&dataScreens.includes(id)&&state.viewState!=='content'){const context={'S04':'ringkasan','S07':'riwayat','S08':'detail','S11':'panduan','S12':'panduan','S13':'statistik','S14':'profil','S15':'achievement'}[id];return header(screens.find(s=>s.id===id).name,navItems.some(x=>x[0]===id)?null:'S04')+emptyState(state.viewState,context);}
 if(Number(id.slice(1))>=21)return aiScreen(id);
 switch(id){
 case 'S01':return `<div style="padding-top:64px" class="stack"><div class="wordmark">WasteNot<span class="brand-dot"></span></div>${emptyState('loading','catatanmu')}${goto('Simulasikan sesi valid','S04')}${goto('Simulasikan tanpa sesi','S02','secondary')}</div>`;
 case 'S02':case 'S03':{const register=id==='S03';return `<div class="wordmark">WasteNot<span class="brand-dot"></span></div><div class="row"><div class="auth-art">${icon(register?'leaf':'recycle')}</div><div class="grow"><h2 class="auth-heading">${register?'Mulai mencatat.':'Masuk kembali.'}</h2><p class="muted">${register?'Buat akun simulasi lokal.':'Lanjutkan catatanmu.'}</p></div></div><form data-form="${register?'register':'login'}" class="group-card glass-form pad">${register?field('Nama','name',{required:true,placeholder:'Nama tampilan',extra:'minlength="2" maxlength="60" autocomplete="off"'}):''}${field('Email','email',{type:'email',required:true,placeholder:'nama@example.com',extra:'maxlength="254" autocomplete="off"'})}<label class="field">Kata sandi<span class="password-wrap"><input name="password" type="password" required minlength="12" maxlength="128" placeholder="Minimal 12 karakter" autocomplete="new-password"><button type="button" class="icon-btn" data-action="password" aria-label="Tampilkan kata sandi">${icon('eye')}</button></span></label>${register?field('Ulangi kata sandi','confirm',{type:'password',required:true,placeholder:'Ketik ulang kata sandi',extra:'autocomplete="new-password"'})+'<p class="small muted">Zona waktu: Asia/Jakarta</p>':''}<p data-form-error role="alert" class="notice error" hidden></p>${button(register?'Buat akun simulasi':'Masuk ke simulasi','type="submit"')}</form>${goto(register?'Sudah punya akun? Masuk':'Belum punya akun? Daftar',register?'S02':'S03','text-btn')}`;}
 case 'S04':{const today=logs.filter(x=>x.date===TODAY),t=totals(today);return `<div class="row between"><div><p class="muted small">Senin, 21 Sep</p><h2 style="margin-top:2px">Halo, ${preview?'Pengguna Demo':esc(state.name)}.</h2></div><button class="icon-btn circle" data-go="S14" aria-label="Buka profil">${icon('user')}</button></div><div class="summary"><div class="summary-top"><p>Ditangani hari ini</p><details class="summary-info"><summary aria-label="Info metode perhitungan">i</summary><p>Catatan pribadi, bukan dampak terverifikasi.</p></details></div><div class="big-value">${number(t.weight>=1000?t.weight/1000:t.weight)} <small>${t.weight>=1000?'kg':'g'}</small></div><div class="summary-pill-row"><span class="summary-pill">${t.activities} aktivitas</span>${t.count?`<span class="summary-pill">${t.count} benda</span>`:''}</div></div><div class="metric-grid"><div class="metric-tile"><div class="metric-tile-head"><span>Recycling rate</span><span class="metric-spark">${icon('recycle')}</span></div><strong>${t.rate===null?'—':number(t.rate)+'%'}</strong></div><div class="metric-tile"><div class="metric-tile-head"><span>Dihindari</span><span class="metric-spark lime">${icon('leaf')}</span></div><strong>${number(t.avoidedCount)} benda</strong></div></div><div class="group-card pad">${progress(logs)}</div>${goto('Input manual','S05','secondary')}<div><div class="subheading"><h3>Aktivitas terbaru</h3><button class="text-link" data-go="S07">Lihat riwayat</button></div>${logs.length?`<div class="group-card">${logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(logRow).join('')}</div>`:emptyState('empty')}</div>`;}
 case 'S05':return editor(preview,false);
 case 'S06':return `${header('Catatan tersimpan',null)}<div class="state-box"><div class="state-symbol" style="background:var(--accent);color:var(--on-accent)">${icon('check')}</div><h3>Satu langkah tercatat.</h3><p>${preview||state.lastNew?'+10 XP ditambahkan.':'Perubahan tersimpan.'}</p></div>${selected?`<div class="group-card">${logRow(selected)}</div>`:''}<div class="stack">${goto('Lihat catatan','S08')}${goto('Kembali ke beranda','S04','secondary')}</div>`;
 case 'S07':{const f=preview?{}:state.filter;const filtered=logs.filter(l=>(!f.category||l.category===f.category)&&(!f.method||l.method===f.method)&&(!f.from||l.date>=f.from)&&(!f.to||l.date<=f.to)).sort((a,b)=>b.date.localeCompare(a.date));const dates=[...new Set(filtered.map(l=>l.date))];return `${header('Riwayat',null,`<button class="icon-btn" data-go="S10" aria-label="Filter riwayat">${icon('filter')}</button>`)}<div class="row between"><span class="small muted">${filtered.length} aktivitas</span>${f.category||f.method||f.from?`<button class="text-link" data-action="clear-filter">Reset</button>`:''}</div>${f.category||f.method||f.from?`<div class="row wrap">${f.category?`<span class="badge">${categories[f.category]}</span>`:''}${f.method?`<span class="badge">${methods[f.method]}</span>`:''}</div>`:''}${filtered.length?dates.map(d=>`<p class="group-label">${d===TODAY?'Hari ini':shortDate(d)}</p><div class="group-card">${filtered.filter(l=>l.date===d).map(logRow).join('')}</div>`).join(''):emptyState(logs.length?'filtered':'empty')}${goto('Input manual','S05','secondary')}`;}
 case 'S08':return `${header('Detail catatan','S07')}${selected?`<div class="group-card pad">${badge(selected.method)}<p class="muted">${categories[selected.category]}</p><div class="detail-number">${value(selected)}</div>${selected.method==='REDUCE'?'<p class="small muted">Dihindari, bukan sampah ditangani.</p>':''}</div><div class="group-card"><div class="detail-meta"><span>Tanggal</span><strong>${shortDate(selected.date)} 2026</strong></div><div class="detail-meta"><span>Zona waktu</span><strong>Asia/Jakarta</strong></div><div class="detail-meta"><span>Metode</span><strong>${methods[selected.method]}</strong></div></div><div class="group-card pad"><span class="group-label" style="padding:0">Catatan</span><p>${esc(selected.notes||'Tanpa catatan.')}</p></div><div class="stack">${goto('Ubah catatan','S09')}${button('Hapus catatan','data-dialog="delete"','secondary')}</div>`:emptyState('empty')}`;
 case 'S09':return selected?editor(preview,true):header('Ubah catatan','S07')+emptyState('empty');
 case 'S10':{const f=preview?{}:state.filter;return `${header('Filter riwayat','S07')}<form data-form="filter" class="group-card glass-form pad"><label class="field">Kategori<select name="category">${optionList(categories,f.category,'Semua kategori')}</select></label><label class="field">Metode<select name="method">${optionList(methods,f.method,'Semua metode')}</select></label>${field('Dari tanggal','from',{type:'date',value:f.from,extra:`max="${TODAY}"`})}${field('Sampai tanggal','to',{type:'date',value:f.to,extra:`max="${TODAY}"`})}<p class="notice error" data-form-error role="alert" hidden></p>${button('Terapkan filter','type="submit"')}${button('Reset pilihan','type="reset"','secondary')}</form>`;}
 case 'S11':{const q=preview?'':state.query;const found=guides.filter(g=>(g.name+' '+categories[g.category]).toLowerCase().includes(q.toLowerCase()));return `${header('Panduan',null)}<form data-form="guide-search" class="group-card glass-form pad"><label class="field">Cari material<input type="search" name="q" value="${esc(q)}" maxlength="100" placeholder="Botol, kaca, kertas…"></label><div class="row">${button(icon('search')+'Cari','type="submit"','secondary')}${button('Hapus','type="button" data-action="clear-search"','text-btn')}</div></form>${found.length?`<div class="group-card">${found.map(g=>`<button class="guide-row" data-guide="${g.id}"><span class="category-icon">${icon(categoryIcons[g.category])}</span><span class="grow"><strong>${g.name}</strong><small>${methods[g.method]} · Draf</small></span>${icon('next')}</button>`).join('')}</div>`:'<div class="state-box"><h3>Panduan belum ditemukan</h3><p>Coba nama material yang lebih umum.</p><button class="btn secondary" data-action="clear-search">Hapus pencarian</button></div>'}`;}
 case 'S12':return `${header('Detail panduan','S11')}<div class="group-card pad"><div class="row"><div class="category-icon" style="width:52px;height:52px">${icon(categoryIcons[guide.category])}</div><div class="grow">${badge(guide.method)}<h2 style="margin-top:6px;font-size:20px">${guide.name}</h2></div></div><p class="muted">${guide.summary}</p></div><p class="group-label">Langkah penanganan</p><div class="group-card">${guide.steps.map((x,i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><p>${x}</p></div>`).join('')}</div><details class="scan-source"><summary>Draf editorial · catatan sumber</summary><p>Penerimaan material berbeda antar fasilitas; sumber dan tanggal review akan terisi saat dipublikasikan.</p></details>${button('Catat aktivitas ini','data-action="guide-prefill"')}`;
 case 'S13':{const range=preview?7:state.range;const start=new Date(TODAY+'T12:00:00Z');start.setUTCDate(start.getUTCDate()-(range-1));const period=logs.filter(l=>l.date>=start.toISOString().slice(0,10)&&l.date<=TODAY);const t=totals(period);return `${header('Statistik',null)}<div class="segment" aria-label="Rentang statistik"><button data-range="7" aria-pressed="${range===7}">7 hari</button><button data-range="30" aria-pressed="${range===30}">30 hari</button></div><div class="summary"><div class="summary-top"><p>${shortDate(start.toISOString().slice(0,10))} – 21 Sep 2026</p></div><div class="big-value">${number(t.weight>=1000?t.weight/1000:t.weight)} <small>${t.weight>=1000?'kg':'g'}</small></div><div class="summary-pill-row"><span class="summary-pill">${t.activities} aktivitas</span>${t.count?`<span class="summary-pill">${t.count} benda</span>`:''}</div></div><div class="metric-grid"><div class="metric-tile"><div class="metric-tile-head"><span>Recycling rate</span><span class="metric-spark">${icon('recycle')}</span></div><strong>${t.rate===null?'—':number(t.rate)+'%'}</strong></div><div class="metric-tile"><div class="metric-tile-head"><span>Dihindari</span><span class="metric-spark lime">${icon('leaf')}</span></div><strong>${t.avoidedCount} benda</strong></div></div><div class="group-card pad"><h3>Tren harian</h3>${chart(period,range)}</div><p class="group-label">Proporsi metode</p><div class="group-card pad">${Object.keys(methods).map(m=>{const n=period.filter(l=>l.method===m).length;return `<div class="breakdown-row"><span>${methods[m]}</span><progress value="${n}" max="${period.length||1}" aria-label="${methods[m]} ${n} dari ${period.length} aktivitas"></progress><strong>${period.length?number(n/period.length*100):0}%</strong></div>`;}).join('')}</div><p class="group-label">Per kategori</p><div class="group-card">${Object.entries(categories).map(([c,label])=>{const ct=totals(period.filter(l=>l.category===c));return `<div class="metric-line"><span>${label}</span><span>${mass(ct.weight)}${ct.count?' · '+ct.count+' benda':''}</span></div>`;}).join('')}</div>`;}
 case 'S14':{const xp=logs.length*10;return `${header('Profil',null)}<div class="group-card pad"><div class="row"><div class="avatar">PD</div><div class="grow"><h3>${preview?'Pengguna Demo':esc(state.name)}</h3><p class="muted small">demo@example.com · Asia/Jakarta</p></div></div>${progress(logs)}</div><div class="metric-grid"><div class="metric-tile"><div class="metric-tile-head"><span>Level</span><span class="metric-spark">${icon('award')}</span></div><strong>${Math.floor(xp/100)+1}</strong></div><div class="metric-tile"><div class="metric-tile-head"><span>Streak aktif</span><span class="metric-spark lime">${icon('clock')}</span></div><strong>${streak(logs)} hari</strong></div></div><div class="group-card">${menuRow('Achievement','S15','award')}${menuRow('Pengaturan','S16','settings')}${menuRow('Titik daur ulang · opsi','S19','pin')}</div>${button(icon('logout')+'Keluar','data-dialog="logout"','secondary')}`;}
 case 'S15':{const achievements=[['Langkah pertama',logs.length,1,'catatan'],['Mulai terbiasa',logs.length,5,'catatan'],['Pilah untuk daur ulang',logs.filter(l=>l.method==='RECYCLE').length,3,'aktivitas Recycle'],['Satu minggu konsisten',bestStreak(logs),7,'hari beruntun']];return `${header('Achievement','S14')}<div class="group-card">${achievements.map(([n,v,t,u])=>`<div class="achievement"><div class="row"><span class="category-icon">${icon(v>=t?'check':'award')}</span><div class="grow"><strong>${n}</strong><span class="small muted">${Math.min(v,t)} / ${t} ${u}</span></div><span class="badge ${v>=t?'recycle':''}">${v>=t?'Tercapai':'Progres'}</span></div><progress value="${Math.min(v,t)}" max="${t}" aria-label="${n}: ${Math.min(v,t)} dari ${t}"></progress><details><summary>Lihat syarat</summary><p>Memerlukan ${t} ${u}. Terkunci kembali jika catatan aktif berkurang.</p></details></div>`).join('')}</div>`;}
 case 'S16':return `${header('Pengaturan','S14')}<p class="group-label">Preferensi</p><div class="group-card"><div class="pad" style="padding:14px 16px"><label class="field">Tema aplikasi<select data-action="theme-select"><option value="system" ${state.theme==='system'?'selected':''}>Ikuti sistem</option><option value="light" ${state.theme==='light'?'selected':''}>Terang</option><option value="dark" ${state.theme==='dark'?'selected':''}>Gelap</option></select></label></div>${menuRow('Pengingat · opsi','S17','bell')}</div><p class="group-label">Akun & privasi</p><div class="group-card"><div class="detail-meta"><span>Zona akun</span><strong>Asia/Jakarta</strong></div><div class="detail-meta"><span>Data pribadi</span><strong>Terisolasi per akun</strong></div><div class="detail-meta"><span>Versi rancangan</span><strong>1.4</strong></div></div>`;
 case 'S17':{return `${header('Pengingat','S16')}<form data-form="reminder" class="group-card glass-form pad"><label class="switch-label"><span>Aktifkan pengingat</span><input name="enabled" type="checkbox" ${!preview&&state.reminder?'checked':''}></label>${field('Sekitar pukul','time',{type:'time',value:preview?'20:00':state.time,required:true,extra:(!preview&&state.reminder?'':'disabled')})}<p class="small muted">Izin notifikasi diminta saat diaktifkan di Android.</p>${button('Simpan pengingat','type="submit"')}</form>`;}
 case 'S18':return `${header('Lampiran foto','S05')}<div class="group-card pad">${!preview&&state.photo?`<img class="photo-preview" src="${esc(state.photo)}" alt="Pratinjau foto yang dipilih"><p class="small muted">${esc(state.photoName)}</p>`:`<div class="photo-empty">${icon('camera')}<span>Belum ada foto dipilih</span></div>`}<label class="field">Pilih gambar lokal<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><p class="small muted">JPEG, PNG, WebP · maks 5 MiB. Opsional.</p><div class="stack">${button('Hapus foto','data-action="remove-photo"','secondary')}${goto('Kembali ke catatan','S05')}</div></div>`;
 case 'S19':return `${header('Titik daur ulang','S14')}<form data-form="location" class="group-card pad">${field('Area pencarian','area',{placeholder:'Kota atau kecamatan',required:true})}${button('Cari area','type="submit"','secondary')}${button(icon('pin')+'Simulasikan izin lokasi','type="button" data-action="location"','text-btn')}</form><div class="group-card pad"><div class="state-box" style="padding:12px 4px"><div class="state-symbol">${icon('pin')}</div><h3>Belum ada titik terverifikasi</h3><p>Dataset fasilitas belum tersedia.</p></div></div>`;
 case 'S20':return `${header('State aplikasi','S04')}<div class="row wrap">${['loading','empty','error','offline','session','filtered'].map(k=>`<button class="chip" data-state-demo="${k}">${{loading:'Loading',empty:'Kosong',error:'Error',offline:'Offline',session:'Sesi',filtered:'Filter'}[k]}</button>`).join('')}</div><div class="group-card pad" data-state-example>${emptyState('empty')}</div><div class="notice success">Catatan tersimpan · +10 XP.</div>`;
 default:return '';
 }
}
function menuRow(label,id,i){return `<button class="menu-row" data-go="${id}"><span><span class="menu-icon-badge">${icon(i)}</span>${label}</span>${icon('next')}</button>`;}
function phone(id,preview=false){return `<div class="statusbar"><span>9:41</span><span>Data simulasi</span></div><div class="phone-scroll" ${preview?'inert':''}><div class="phone-content">${screenContent(id,preview)}</div></div>${navItems.some(n=>n[0]===id)?`<div ${preview?'inert':''}>${nav(id)}</div>`:''}`;}
function renderLive(){const meta=screens.find(s=>s.id===state.route);const el=$('#live-phone');el.classList.toggle('has-nav',navItems.some(n=>n[0]===state.route));el.innerHTML=phone(state.route);$('#screen-select').value=state.route;$('#state-select').value=state.viewState;$('#live-label').textContent=meta.id+' / '+meta.name;$('#live-description').textContent=meta.description;}
function renderGallery(){const visible=screens.filter(s=>state.galleryGroup==='all'||s.group===state.galleryGroup);$('#screen-count').textContent=visible.length+' layar ditampilkan';$('#screen-gallery').innerHTML=visible.map(s=>`<article class="gallery-item" data-screen="${s.id}"><div class="gallery-meta"><h3>${s.id} · ${s.name}</h3><span class="scope">${s.scope}</span></div><div class="phone ${navItems.some(n=>n[0]===s.id)?'has-nav':''}">${phone(s.id,true)}</div><p class="small muted">${s.description}</p><button class="btn secondary" data-open="${s.id}">Coba layar ${s.id}</button></article>`).join('');}
function renderCover(){$('#cover-phone').innerHTML=phone('S04',true);}
function navigate(id,force=false){if(!screens.some(s=>s.id===id))return;if(!force&&state.dirty&&['S05','S09'].includes(state.route)&&id!=='S18'){pendingRoute=id;openDialog('discard');return;}const old=state.route;if(id==='S05'&&old!=='S18'){state.draft=newDraft();state.dirty=false;}if(id==='S09'){const selected=state.logs.find(x=>x.id===state.selectedId)||state.logs[0];state.draft=selected?draftFor(selected):newDraft();state.dirty=false;}state.route=id;state.viewState='content';renderLive();}
function openScreen(id){navigate(id);$('#prototype').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;$('#theme').value=theme;const local=$('#live-phone [data-action="theme-select"]');if(local)local.value=theme;}
let dialogKind=null,pendingRoute=null,lastFocus=null;
const dialogs={delete:['Hapus catatan?','Catatan ini akan dihapus dari simulasi. Statistik, XP, dan achievement akan dihitung ulang.','Hapus catatan','bin'],logout:['Keluar dari akun?','Kamu perlu masuk lagi untuk membuka catatan. Simulasi ini akan membersihkan data sesi.','Keluar','logout'],discard:['Buang perubahan?','Perubahan belum disimpan. Kamu bisa kembali melanjutkan pengisian.','Buang perubahan','alert'],conflict:['Catatan telah berubah','Ini simulasi konflik versi. Muat versi terbaru sebelum mencoba menyimpan kembali.','Muat versi terbaru','history']};
function openDialog(kind){dialogKind=kind;lastFocus=document.activeElement;const [title,body,cta,i]=dialogs[kind];$('#dialog-body').innerHTML=`<div class="state-symbol">${icon(i)}</div><h2 id="dialog-title">${title}</h2><p>${body}</p><div class="stack">${button(cta,'data-action="confirm-dialog"',kind==='delete'||kind==='discard'?'destructive':'primary')}${button(kind==='discard'?'Lanjut mengisi':'Batal','data-action="cancel-dialog"','secondary')}</div>`;$('#app-dialog').showModal();$('#app-dialog [data-action="cancel-dialog"]').focus();}
function closeDialog(){$('#app-dialog').close();if(lastFocus?.isConnected)lastFocus.focus();}
function confirmDialog(){const kind=dialogKind;closeDialog();if(kind==='delete'){const id=state.selectedId||state.logs[0]?.id;state.logs=state.logs.filter(l=>l.id!==id);state.selectedId=state.logs[0]?.id;state.dirty=false;navigate('S07',true);toast('Catatan dihapus. Statistik dan XP diperbarui.');}if(kind==='logout'){state.logs=[];state.draft=null;state.dirty=false;state.reminder=false;state.name='Pengguna Demo';state.filter={category:'',method:'',from:'',to:''};if(state.photo)URL.revokeObjectURL(state.photo);state.photo=null;navigate('S02',true);toast('Keluar dari sesi simulasi.');}if(kind==='discard'){state.dirty=false;state.draft=null;const id=pendingRoute||'S04';pendingRoute=null;navigate(id,true);}if(kind==='conflict'){state.dirty=false;navigate('S09',true);toast('Versi terbaru dimuat dalam simulasi.');}}
function formError(form,message,name){const el=form.querySelector('[data-form-error]');if(el){el.textContent=message;el.hidden=false;}if(name){const control=form.elements.namedItem(name);if(control instanceof HTMLElement){control.setAttribute('aria-invalid','true');control.focus();}}}
function readDraft(form){return Object.fromEntries(new FormData(form).entries());}
function renderComponents(){const components=[
 ['C01','Wordmark','Text + FontFamily',`<span class="wordmark">WasteNot<span class="brand-dot"></span></span>`,'Teks merek, belum logo final. Plus Jakarta Sans 800.'],
 ['C02','App bar','TopAppBar',`<div class="phone-title full"><button class="icon-btn" data-open="S07" aria-label="Buka riwayat">${icon('back')}</button><h3>Detail catatan</h3></div>`,'Judul dan aksi kembali, target 48 dp.'],
 ['C03','Primary button','Button',button('Simpan catatan','data-demo="Contoh feedback: catatan tersimpan."')+button('Disabled','disabled')+button('Menyimpan…','disabled'),'Default, disabled, dan busy. Contoh tidak mengubah dataset.'],
 ['C04','Secondary button','OutlinedButton',button('Lihat riwayat','data-open="S07"','secondary'),'Untuk tindakan pendukung, dengan batas kontrol terlihat.'],
 ['C05','Text action','TextButton',button('Baca panduan','data-open="S11"','text-btn'),'Tindakan tersier tetap memiliki target sentuh.'],
 ['C06','Icon button','IconButton',`<button class="icon-btn" data-open="S10" aria-label="Buka filter">${icon('filter')}</button><button class="icon-btn" data-open="S16" aria-label="Buka pengaturan">${icon('settings')}</button>`,'Ikon aksi tunggal wajib memiliki nama aksesibel.'],
 ['C07','Input manual','OutlinedButton',button('Input manual','data-open="S05"','secondary'),'Aksi pendukung di Beranda dan Riwayat; Catat/Scan menjadi aksi utama dock.'],
 ['C08','Text field','OutlinedTextField',`<label class="field">Catatan<input placeholder="Tambahkan konteks aktivitas" maxlength="500"></label><label class="field">Contoh field error<input class="error-field" value="0" aria-invalid="true" aria-describedby="example-error"><span id="example-error" class="field-error">Berat minimal 1 gram.</span></label>`,'Label persisten, error tertulis, nilai tidak hilang.'],
 ['C09','Password field','TextField',`<label class="field">Kata sandi<span class="password-wrap"><input type="password" value="contoh-saja-123" autocomplete="new-password"><button class="icon-btn" data-action="password" aria-label="Tampilkan kata sandi">${icon('eye')}</button></span></label>`,'Tampil/sembunyikan tidak mengubah isi field.'],
 ['C10','Search','TextField',`<label class="field">Cari material<input type="search" data-component-search placeholder="Ketik plastik atau kertas"></label><span class="small muted" data-component-search-result>Masukkan kata untuk melihat feedback.</span>`,'Pencarian produksi menggunakan endpoint panduan.'],
 ['C11','Quantity field','TextField + unit',`<div class="field full"><span class="field-label">Berat</span><div class="quantity-compound"><input inputmode="decimal" aria-label="Berat" value="250"><select aria-label="Satuan"><option>g</option><option>kg</option><option>Benda</option></select></div></div>`,'Satuan selalu terlihat menyatu. Validasi lengkap dapat dicoba di S05.'],
 ['C12','Category picker','ExposedDropdownMenu',`<label class="field">Kategori<select>${optionList(categories,'PLASTIC')}</select></label>`,'Kategori manual atau hasil scan yang sudah dikonfirmasi; selalu dapat dikoreksi.'],
 ['C13','Method selector','RadioButton',`<div class="method-options">${Object.entries(methods).map(([k,v],i)=>`<label class="method-option"><input type="radio" name="component-method" value="${k}" ${i===2?'checked':''}><span>${v}</span></label>`).join('')}</div>`,'Empat pilihan, hanya satu aktif.'],
 ['C14','Filter chip','FilterChip',`<button class="chip" data-action="chip" aria-pressed="true">Plastik</button><button class="chip" data-action="chip" aria-pressed="false">Kertas</button>`,'Contoh chip dapat diaktifkan dan dinonaktifkan.'],
 ['C15','Range selector','SegmentedButton',`<div class="segment"><button data-component-range="7" aria-pressed="true">7 hari</button><button data-component-range="30" aria-pressed="false">30 hari</button></div>`,'Pilihan tunggal. Statistik nyata prototype ada di S13.'],
 ['C16','Method badge','Surface + Text',Object.keys(methods).map(badge).join(''),'Status noninteraktif; kata metode tidak bergantung warna.'],
 ['C17','Waste log row','ListItem',logRow(seed[0]),'Kategori, metode, tanggal, dan nilai. Klik membuka detail simulasi.'],
 ['C18','Summary surface','Surface',`<div class="summary"><p>Sampah ditangani · data simulasi</p><div class="big-value">650 <small>g</small></div><p class="muted">3 aktivitas hari ini</p></div>`,'Satu angka dominan. Benda dihindari berada di bidang terpisah.'],
 ['C19','XP progress','LinearProgressIndicator',`<div class="stack">${progress(seed)}</div>`,'Data simulasi 50 XP; aksesibilitas menyebut current dan target.'],
 ['C20','Achievement row','ListItem + Progress',`<div class="stack"><div class="row">${icon('award')}<strong>Pilah untuk daur ulang</strong></div><progress max="3" value="2" aria-label="2 dari 3 aktivitas Recycle"></progress><p class="small muted">2/3 aktivitas Recycle · data simulasi</p>${goto('Lihat achievement','S15','secondary')}</div>`,'Status terkunci tetap mudah dibaca.'],
 ['C21','Guide row','ListItem',`<button class="guide-row" data-guide="bottle"><span class="category-icon">${icon('bottle')}</span><span class="grow"><strong>Botol plastik</strong><small>Draf panduan · Recycle</small></span>${icon('next')}</button>`,'Buka detail. Konten contoh belum diverifikasi.'],
 ['C22','Bar chart','Canvas + semantics',`<div class="stack">${chart(seed)}</div>`,'Data simulasi. Grafik mempunyai ringkasan dan angka harian.'],
 ['C23','Method breakdown','Rows + Progress',`<div class="stack">${Object.keys(methods).map(m=>{const n=seed.filter(l=>l.method===m).length;return `<div class="breakdown-row"><span>${methods[m]}</span><progress value="${n}" max="5" aria-label="${m} ${n} dari 5"></progress><strong>${n*20}%</strong></div>`;}).join('')}</div>`,'Lima aktivitas simulasi, denominator seluruh aktivitas.'],
 ['C24','Bottom navigation','NavigationBar',nav('S04'),'Lima tujuan utama + aksi Catat/Scan di tengah atas dock, membuka bottom sheet kamera.'],
 ['C25','Navigation rail','NavigationRail',`<div class="rail-sample"><nav aria-label="Contoh navigation rail">${navItems.map(([id,label,i])=>`<button data-open="${id}" aria-label="${label}">${icon(i)}</button>`).join('')}</nav><p>Rancangan navigasi untuk lebar mulai 600 dp. Form tetap dibatasi agar nyaman dibaca.</p></div>`,'Label lengkap perlu terlihat di rail produksi sesuai ruang.'],
 ['C26','Filter sheet','ModalBottomSheet',button('Buka filter sheet','data-action="filter-sheet"','secondary'),'Overlay dapat dibatalkan; Apply memperbarui daftar.'],
 ['C27','Confirmation','AlertDialog',button('Coba dialog hapus','data-dialog="delete"','secondary'),'Konfirmasi spesifik, cancel jelas, Escape dapat menutup.'],
 ['C28','Snackbar / banner','SnackbarHost',button('Tampilkan feedback','data-demo="Contoh: catatan tersimpan. Statistik diperbarui."','secondary'),'Feedback transient. Error penting tetap terlihat di form.'],
 ['C29','Async state','Shared composable',`<div class="stack"><div class="notice">Belum ada catatan hari ini.</div>${goto('Lihat semua state','S20','secondary')}</div>`,'Loading, empty, error, offline, sesi, dan success.'],
 ['C30','Reminder switch','Switch',`<label class="switch-label full"><span>Contoh pengingat</span><input type="checkbox" data-action="component-reminder"></label>`,'Contoh hanya mengubah state UI, tidak mengirim notifikasi.'],
 ['C31','Date / time','DatePicker / TimePicker',`<div class="stack">${field('Tanggal aktivitas','example-date',{type:'date',value:TODAY,extra:`max="${TODAY}"`})}${field('Waktu pengingat','example-time',{type:'time',value:'20:00'})}</div>`,'Native controls di HTML, picker Material di Android.'],
 ['C32','Photo attachment','Photo Picker',button(icon('camera')+'Coba preview foto','data-open="S18"','secondary'),'Gambar lokal opsional, tanpa foto stok pengguna fiktif.'],
 ['C33','Source link','Open URI',`<a href="PRD.md">Baca sumber kebutuhan: PRD.md</a>`,'Artikel produksi harus memiliki sumber dan tanggal review nyata.'],
 ['C35','Scan action','Button',button(icon('camera')+'Catat / Scan','data-scan-open="camera"'),'Aksi utama dock, bukan tab keenam.'],
 ['C36','Camera bottom sheet','ModalBottomSheet',button('Buka kamera dan fallback','data-scan-open="camera"','secondary'),'Capture lokal, izin kamera, manual selalu tersedia.'],
 ['C37','Detection review','ListItem + overlay',button('Periksa contoh deteksi','data-scan-open="objects"','secondary'),'Bbox dan daftar, skor bukan kepastian.'],
 ['C38','Object context','Selection controls',button('Isi kondisi objek','data-scan-open="context"','secondary'),'Kondisi terpisah, pilihan belum tahu.'],
 ['C39','Recommendation review','Surface + Select',button('Periksa contoh saran','data-scan-open="recommendation"','secondary'),'Konfirmasi metode sebelum jumlah; tidak auto-save.'],
 ['C34','Category icons','VectorDrawable',`<div class="row wrap">${Object.entries(categories).map(([k,v])=>`<div class="stack" style="align-items:center;gap:6px"><span class="category-icon">${icon(categoryIcons[k])}</span><span class="small">${v}</span></div>`).join('')}</div>`,'Tujuh simbol material, selalu dibantu label teks.']
 ];
 $('#component-grid').innerHTML=components.sort((a,b)=>a[0].localeCompare(b[0])).map(([id,title,compose,demo,description])=>`<article class="component" id="${id}"><div class="component-head"><h3>${id} · ${title}</h3></div><div class="component-demo">${demo}</div><p><strong>${compose}</strong><br>${description}</p></article>`).join('');
}
function resetDemo(){state.logs=structuredClone(seed);state.selectedId='DEMO-01';state.draft=null;state.dirty=false;state.query='';state.filter={category:'',method:'',from:'',to:''};state.range=7;state.name='Pengguna Demo';state.reminder=false;state.time='20:00';state.lastNew=true;if(state.photo)URL.revokeObjectURL(state.photo);state.photo=null;state.photoName='';navigate('S04',true);toast('Data simulasi dikembalikan ke lima catatan awal.');}
document.addEventListener('click',event=>{
 const el=event.target.closest('button,a');if(!el||el.closest('[inert]'))return;
 if(el.dataset.open){openScreen(el.dataset.open);return;}
 if(el.dataset.go){if($('#app-dialog').open)closeDialog();navigate(el.dataset.go);if(!el.closest('#live-phone'))$('#prototype').scrollIntoView();return;}
 if(el.dataset.log){state.selectedId=el.dataset.log;if(!state.logs.some(l=>l.id===el.dataset.log)){toast('Data contoh ini sudah dihapus. Reset demo untuk memulihkannya.');return;}openScreen('S08');return;}
 if(el.dataset.guide){state.guideId=el.dataset.guide;openScreen('S12');return;}
 if(el.dataset.dialog){if(el.dataset.dialog==='delete'&&!state.logs.length){toast('Belum ada catatan untuk dihapus.');return;}openDialog(el.dataset.dialog);return;}
 if(el.dataset.demo){toast(el.dataset.demo);return;}
 if(el.dataset.range){state.range=Number(el.dataset.range);renderLive();return;}
 if(el.dataset.componentRange){el.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));toast('Contoh periode: '+el.dataset.componentRange+' hari.');return;}
 if(el.dataset.stateDemo){$('#live-phone [data-state-example]').innerHTML=emptyState(el.dataset.stateDemo);return;}
 switch(el.dataset.action){
 case 'reset-demo':resetDemo();break;
 case 'retry':state.viewState='content';renderLive();toast('Koneksi dipulihkan dalam simulasi.');break;
 case 'clear-filter':state.filter={category:'',method:'',from:'',to:''};navigate('S07',true);break;
 case 'clear-search':state.query='';renderLive();break;
 case 'guide-prefill':{const guide=guides.find(g=>g.id===state.guideId);navigate('S05',true);state.draft={...newDraft(),category:guide.category,method:guide.method};renderLive();break;}
 case 'password':{const input=el.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi');break;}
 case 'chip':el.setAttribute('aria-pressed',String(el.getAttribute('aria-pressed')!=='true'));break;
 case 'confirm-dialog':confirmDialog();break;
 case 'cancel-dialog':closeDialog();break;
 case 'filter-sheet':lastFocus=el;$('#dialog-body').innerHTML=`<h2 id="dialog-title">Filter riwayat</h2><form data-form="filter" class="stack"><label class="field">Kategori<select name="category">${optionList(categories,state.filter.category,'Semua kategori')}</select></label><label class="field">Metode<select name="method">${optionList(methods,state.filter.method,'Semua metode')}</select></label><input type="hidden" name="from" value=""><input type="hidden" name="to" value=""><p data-form-error class="notice error" role="alert" hidden></p>${button('Terapkan filter','type="submit"')}${button('Batal','type="button" data-action="cancel-dialog"','secondary')}</form>`;$('#app-dialog').showModal();break;
 case 'remove-photo':if(state.photo)URL.revokeObjectURL(state.photo);state.photo=null;state.photoName='';renderLive();toast('Preview foto dihapus.');break;
 case 'location':toast('Simulasi: izin lokasi ditolak. Pencarian area tetap tersedia.');break;
 }
});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('[inert]'))return;if(el.hasAttribute('data-component-search')){$('[data-component-search-result]').textContent=el.value?'Pencarian contoh: '+el.value:'Masukkan kata untuk melihat feedback.';}
 const form=el.closest('#live-phone form[data-form="log"]');if(form&&el.name!=='unit'){state.draft=readDraft(form);state.dirty=true;el.removeAttribute('aria-invalid');}
});
document.addEventListener('change',event=>{const el=event.target;if(el.closest('[inert]'))return;
 if(el.id==='theme'||el.dataset.action==='theme-select'){setTheme(el.value);return;}
 if(el.id==='screen-filter'){state.galleryGroup=el.value;renderGallery();return;}
 if(el.id==='screen-select'){navigate(el.value);return;}
 if(el.id==='state-select'){state.viewState=el.value;renderLive();return;}
 if(el.dataset.action==='component-reminder'){toast(el.checked?'Contoh switch aktif, belum ada jadwal.':'Contoh switch nonaktif.');return;}
 const logForm=el.closest('#live-phone form[data-form="log"]');if(logForm&&['method','unit'].includes(el.name)){const previous=state.draft;state.draft=readDraft(logForm);if(el.name==='unit'&&previous){const q=parseQuantity(previous.quantity,previous.unit);state.draft.quantity=q&&previous.unit!=='pcs'&&el.value!=='pcs'?String(el.value==='kg'?q.weight/1000:q.weight):'';}state.dirty=true;renderLive();return;}
 const reminder=el.closest('form[data-form="reminder"]');if(reminder&&el.name==='enabled'){reminder.elements.time.disabled=!el.checked;return;}
 if(el.name==='photo'&&el.files?.length){const file=el.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){el.value='';toast('Pilih JPEG, PNG, atau WebP maksimal 5 MiB.');return;}const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{if(state.photo)URL.revokeObjectURL(state.photo);state.photo=url;state.photoName=file.name;if(state.route==='S18')renderLive();toast('Preview lokal siap. Tidak ada file yang diunggah.');};img.onerror=()=>{URL.revokeObjectURL(url);toast('Gambar tidak dapat dibaca. Pilih file lain.');};img.src=url;}
});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form||form.closest('[inert]'))return;event.preventDefault();const data=Object.fromEntries(new FormData(form).entries());
 switch(form.dataset.form){
 case 'login':case 'register':if(form.dataset.form==='register'&&(data.name.trim().length<2||data.name.trim().length>60)){formError(form,'Isi nama sepanjang 2–60 karakter.','name');return;}if(form.dataset.form==='register'&&data.password!==data.confirm){formError(form,'Kata sandi belum sama.','confirm');return;}state.name=form.dataset.form==='register'?data.name.trim():'Pengguna Demo';form.reset();navigate('S04',true);toast('Berhasil masuk ke simulasi lokal.');break;
 case 'log':{const quantity=parseQuantity(data.quantity,data.unit);if(!Object.hasOwn(methods,data.method)){formError(form,'Pilih cara pengelolaan.');return;}if(!Object.hasOwn(categories,data.category)){formError(form,'Pilih kategori.','category');return;}if(!quantity){formError(form,data.unit==='pcs'?'Masukkan jumlah bulat 1–10.000 benda.':'Berat harus 1 g–100 kg. kg maksimal 3 desimal.','quantity');return;}const selected=state.logs.find(l=>l.id===state.selectedId);const preservedDate=state.route==='S09'&&selected?.date===data.date;if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||data.date>TODAY||(!preservedDate&&data.date<MIN_DATE)){formError(form,'Pilih tanggal dalam 30 hari terakhir.','date');return;}if((data.notes||'').length>500){formError(form,'Catatan maksimal 500 karakter.','notes');return;}if(['offline','error'].includes(state.viewState)){formError(form,'Belum tersimpan. Isianmu tetap tersedia. Pilih state Konten untuk menyimulasikan koneksi pulih.');return;}const editing=state.route==='S09';const log={id:editing?state.selectedId:'LOCAL-'+crypto.randomUUID(),category:data.category,method:data.method,...quantity,date:data.date,notes:(data.notes||'').trim()};if(editing){state.logs=state.logs.map(l=>l.id===log.id?log:l);}else state.logs.unshift(log);state.selectedId=log.id;state.dirty=false;state.draft=null;state.lastNew=!editing;navigate(editing?'S08':'S06',true);toast(editing?'Perubahan tersimpan. XP tidak bertambah.':'Catatan tersimpan. +10 XP.');break;}
 case 'filter':if(Boolean(data.from)!==Boolean(data.to)){formError(form,'Isi tanggal mulai dan akhir, atau kosongkan keduanya.');return;}if(data.from&&data.from>data.to){formError(form,'Tanggal mulai tidak boleh melewati tanggal akhir.');return;}state.filter=data;if($('#app-dialog').open)closeDialog();navigate('S07',true);$('#prototype').scrollIntoView();break;
 case 'guide-search':state.query=data.q.trim();renderLive();break;
 case 'reminder':state.reminder=data.enabled==='on';state.time=data.time||state.time;toast(state.reminder?`Preferensi simulasi tersimpan: sekitar ${state.time}. Tidak ada notifikasi nyata.`:'Pengingat simulasi dinonaktifkan.');break;
 case 'location':toast('Belum ada data fasilitas terverifikasi untuk area ini.');break;
 }
});
$('#app-dialog').addEventListener('cancel',()=>{pendingRoute=null;});
$('#app-dialog').addEventListener('close',()=>{$('#screen-select').value=state.route;if(lastFocus?.isConnected)lastFocus.focus();});
document.addEventListener('reset',event=>{if(event.target.dataset.form==='filter'){event.preventDefault();for(const field of ['category','method','from','to'])event.target.elements[field].value='';const error=event.target.querySelector('[data-form-error]');if(error)error.hidden=true;}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')setTheme('system');});
$('#screen-select').innerHTML=screens.map(s=>`<option value="${s.id}">${s.id} · ${s.name}</option>`).join('');
$('#swatches').innerHTML=[['Pine','#146342','#FFFFFF','Aksi utama'],['Lime','#CEF067','#172B08','Aksen & scan'],['Mint','#ECF3EC','#122118','Latar lembut'],['Ink','#122118','#FFFFFF','Teks utama'],['White','#FFFFFF','#122118','Kartu & form']].map(([n,color,text,use])=>`<div class="swatch"><div class="swatch-color" style="background:${color};color:${text}">${n}<br>${color}</div><p>${use}</p></div>`).join('');
$('#spacing-samples').innerHTML=[4,8,12,16,20,24,32].map(n=>`<div><i style="height:${n*1.8}px"></i>${n}</div>`).join('');
renderCover();renderComponents();renderGallery();renderLive();setTheme('light');
window.WasteNotDemo={totals,parseQuantity,streak,bestStreak,seed,resetDemo,getState:()=>state};
